"use client"

import * as React from "react"

import { Badge } from "@/components/ui/badge"
import { Button } from "@/components/ui/button"
import { Separator } from "@/components/ui/separator"
import { cn } from "@/lib/utils"
import {
  CALL_DETAIL,
  type CallIdentity,
  type CallState,
  type Channel,
  type RevampTurn,
} from "@/lib/mockups/conversations-revamp-drawer-data"
import {
  AgentIcon,
  CallerIcon,
  CompletedIcon,
  CopyIcon,
  CopyLinkIcon,
  HumanAgentIcon,
  LanguageIcon,
  OrganizationIcon,
  ChatChannelIcon,
  OutboundIcon,
  OwnerIcon,
  QueuedIcon,
  ScheduledIcon,
} from "@/components/mockups/conversations-revamp/drawer/icons"

/**
 * The pieces the drawer shares across its transcript and its section panel.
 *
 * They came out of the earlier drawer variants, which this mockup does not
 * carry — only revamp 4 ships here, so the parts it still needs live on their
 * own rather than inside a variant nobody renders.
 */

/**
 * The metadata that gets read, in one line under the title. The two IDs sit
 * beside the title as buttons, the way the copy-link button already did.
 */
export function CallHeader({
  /** Appended after Link and Call ID. Omitted, the header is unchanged. */
  actions,
  channel = "call",
  state = "complete",
  title,
}: {
  actions?: React.ReactNode
  /** A chat has no phone number to print in the rail. */
  channel?: Channel
  /** A call that has not run has no duration and no time it started. */
  state?: CallState
  /**
   * The clicked row. Without it the header printed one hardcoded call for
   * every row in the table, so opening the 3307 Instalment Plan Offer read as
   * the 4477 Collections Follow Up. The rest of the rail — organization,
   * owner, language — is still the shared sample.
   */
  title?: CallIdentity
} = {}) {
  const call = CALL_DETAIL
  const scenario = title?.scenario ?? call.scenario
  const phoneNumber = title?.phoneNumber ?? call.phoneNumber
  const startedAt = title?.startedAt ?? call.startedAt
  const duration = title?.duration ?? call.connectionDuration
  const ran = state === "complete"
  const isChat = channel === "chat"

  return (
    <div className="flex shrink-0 flex-col gap-2 border-b p-4">
      <div className="flex items-start justify-between gap-4">
        <div className="flex min-w-0 flex-col gap-1">
          <div className="flex items-center gap-2">
            <h2 className="truncate text-xl font-semibold text-foreground">
              {scenario}
            </h2>
            {ran ? (
              <Badge className="bg-success-tint text-success-tint-foreground">
                <CompletedIcon />
                {call.status}
              </Badge>
            ) : state === "scheduled" ? (
              <Badge className="bg-primary-tint text-primary-tint-foreground">
                <ScheduledIcon />
                scheduled
              </Badge>
            ) : (
              <Badge className="bg-warning-tint text-warning-tint-foreground">
                <QueuedIcon />
                queued
              </Badge>
            )}
          </div>

          <div className="flex flex-wrap items-center gap-x-3 gap-y-1 text-xs text-muted-foreground">
            {/* A chat has no number and no direction. The channel takes the
                slot instead of leaving a gap, so the rail still opens with what
                kind of session this is. */}
            <span className="flex items-center gap-1 font-medium text-foreground">
              {isChat ? (
                <ChatChannelIcon className="size-3.5" />
              ) : (
                <OutboundIcon className="size-3.5" />
              )}
              {isChat ? "Chat" : phoneNumber}
            </span>
            <Separator className="h-3" orientation="vertical" />
            <span className="flex items-center gap-1">
              <OrganizationIcon className="size-3.5" />
              {call.organization}
            </span>
            <span className="flex items-center gap-1">
              <OwnerIcon className="size-3.5" />
              {call.user}
            </span>
            <span className="flex items-center gap-1">
              <LanguageIcon className="size-3.5" />
              {call.language}
            </span>
            {/* A call that has not run has no start time and no duration, and
                printing the ones from a finished call would be a lie the
                reader has no way to spot. */}
            {ran ? (
              <>
                <Separator className="h-3" orientation="vertical" />
                <span>{startedAt}</span>
                <span>{duration}</span>
              </>
            ) : null}
          </div>
        </div>

        <div className="flex shrink-0 items-center gap-1">
          <Button size="sm" variant="ghost">
            <CopyLinkIcon />
            Link
          </Button>
          <Button size="sm" variant="ghost">
            <CopyIcon />
            Call ID
          </Button>
          {actions}
        </div>
      </div>
    </div>
  )
}

/**
 * A clickable surface that is not a Button: the bubbles, chips and the waveform
 * track carry their own shape, and a Button would fight its own padding and
 * radius. Keyboard behaviour is the part that has to be kept by hand.
 */
export function Seekable({
  children,
  className,
  enabled = true,
  label,
  onActivate,
}: {
  children: React.ReactNode
  className?: string
  /**
   * False on a chat, where there is no recording to seek into. The turn still
   * renders identically — it just stops claiming to be clickable, because a
   * pointer cursor and a focus ring on something that does nothing is worse
   * than no affordance at all.
   */
  enabled?: boolean
  label: string
  onActivate: () => void
}) {
  if (!enabled) {
    return <div className={className}>{children}</div>
  }

  return (
    <div
      aria-label={label}
      className={cn(
        "cursor-pointer focus-visible:ring-2 focus-visible:ring-ring focus-visible:outline-none",
        className,
      )}
      onClick={onActivate}
      onKeyDown={(event) => {
        if (event.key === "Enter" || event.key === " ") {
          event.preventDefault()
          onActivate()
        }
      }}
      role="button"
      tabIndex={0}
    >
      {children}
    </div>
  )
}

export function SpeakerAvatar({ role }: { role: RevampTurn["role"] }) {
  return (
    <span
      className={cn(
        "flex size-8 shrink-0 items-center justify-center rounded-4xl",
        role === "caller"
          ? "bg-muted text-foreground"
          : "bg-primary/10 text-primary",
      )}
    >
      {role === "caller" ? (
        <CallerIcon className="size-4" />
      ) : role === "human agent" ? (
        <HumanAgentIcon className="size-4" />
      ) : (
        <AgentIcon className="size-4" />
      )}
    </span>
  )
}

"use client"

import { Badge } from "@/components/ui/badge"
import type { ScheduleDetail } from "@/lib/mockups/conversations-revamp-drawer-data"
import {
  CalendarIcon,
  RequestedIcon,
} from "@/components/mockups/conversations-revamp/drawer/icons"

/**
 * How a booking reads once the call has actually run.
 *
 * Same facts as the pre-call panel, past tense and without the controls: the
 * booking cannot be cancelled or rescheduled any more, so a Cancel call button
 * here would be a dead affordance. What is left is the question a reader
 * arrives with — this call was booked, so what was it booked *for*, and did the
 * agent get the brief we meant to give it?
 *
 * Dial attempts stay, because "connected on the second attempt" explains a
 * customer who sounded surprised. Reschedules stay for the same reason: a call
 * that was moved twice is a different conversation from one that was not.
 */
export function CompletedScheduleSummary({
  schedule,
}: {
  schedule: ScheduleDetail
}) {
  const requested = schedule.origin === "requested"

  return (
    <div className="flex flex-col gap-3 rounded-lg bg-muted p-4">
      <div className="flex flex-wrap items-center justify-between gap-2">
        <span className="text-sm font-medium text-foreground">
          Booked as {schedule.trigger.toLowerCase()}
        </span>

        <Badge
          className={
            requested
              ? "bg-success-tint text-success-tint-foreground"
              : "bg-warning-tint text-warning-tint-foreground"
          }
          variant="secondary"
        >
          {requested ? <RequestedIcon /> : <CalendarIcon />}
          {requested ? "Customer requested" : "Inferred follow-up"}
        </Badge>
      </div>

      <div className="grid gap-3 sm:grid-cols-3">
        <Fact label="Was due" value={schedule.dialsAt} />
        <Fact
          label="Reschedules used"
          value={`${schedule.reschedules.used} of ${schedule.reschedules.limit}`}
        />
        <Fact
          label="Dial attempts used"
          value={`${schedule.dialAttempts.used} of ${schedule.dialAttempts.limit}`}
        />
      </div>

      <div className="flex flex-col gap-1">
        <span className="text-xs text-muted-foreground">
          Context brief the agent was given
        </span>
        <p className="text-sm leading-relaxed text-foreground">
          {schedule.contextBrief}
        </p>
      </div>
    </div>
  )
}

function Fact({ label, value }: { label: string; value: string }) {
  return (
    <div className="flex flex-col gap-1">
      <span className="text-xs text-muted-foreground">{label}</span>
      <span className="rounded-lg bg-card px-3 py-2 text-sm text-foreground">
        {value}
      </span>
    </div>
  )
}

"use client"

import * as React from "react"
import type { PanelImperativeHandle } from "react-resizable-panels"

import { Button } from "@/components/ui/button"
import {
  Dialog,
  DialogClose,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
  DialogTrigger,
} from "@/components/ui/dialog"
import { Field, FieldLabel } from "@/components/ui/field"
import {
  ResizableHandle,
  ResizablePanel,
  ResizablePanelGroup,
} from "@/components/ui/resizable"
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select"
import {
  Sheet,
  SheetContent,
  SheetDescription,
  SheetTitle,
} from "@/components/ui/sheet"
import { Textarea } from "@/components/ui/textarea"
import { cn } from "@/lib/utils"
import {
  CALL_DETAIL,
  CALL_FLAGS,
  ISSUE_TYPE_LABELS,
  ISSUE_TYPE_ORDER,
  type CallIdentity,
  type CallSpecifics,
  type CallState,
  type Channel,
  type IssueType,
} from "@/lib/mockups/conversations-revamp-drawer-data"
import { CallHeader } from "@/components/mockups/conversations-revamp/drawer/call-shell"
import { PreCallPanel } from "@/components/mockups/conversations-revamp/drawer/pre-call-panel"
import { CompletedScheduleSummary } from "@/components/mockups/conversations-revamp/drawer/completed-schedule-summary"
import { LinkedCall } from "@/components/mockups/conversations-revamp/drawer/linked-call"
import {
  ISSUE_TONE,
  SectionRegister,
} from "@/components/mockups/conversations-revamp/drawer/section-register"
import { TranscriptPanel } from "@/components/mockups/conversations-revamp/drawer/transcript-views"
import { formatTimeSeconds } from "@/components/mockups/conversations-revamp/drawer/recording-player"
import {
  FlagIcon,
  ShowPanelIcon,
} from "@/components/mockups/conversations-revamp/drawer/icons"

/**
 * Variant four: the drawer with the review feedback applied.
 *
 * Four changes, and each one is answering something the earlier variants got
 * wrong rather than something they merely lacked:
 *
 *   Transcript  One view, not a choice of views: the enhanced transcription
 *               with every STT mishearing struck through in the line it
 *               happened in. Plus search, since a transcript you cannot search
 *               is a transcript you re-read.
 *   Insights    No success or failure — an insight has a category and no status.
 *               That was factually wrong before, not just unpolished.
 *   Split       A drag handle between the two halves. How much room a transcript
 *               needs against how much the panel needs is a per-reader answer,
 *               so it stops being a number we picked.
 *   Panel       Order and visibility are the reader's, and they are remembered.
 *
 * The drawer width itself stays fixed. Expanding from info to transcript came up
 * in review and was explicitly deferred.
 */
export function FourthDrawer({
  channel = "call",
  onCancelCall,
  onOpenChange,
  open,
  specifics = {},
  state = "complete",
  title,
}: {
  /**
   * Chat sessions open the same drawer minus the three things a chat does not
   * have: a recording, a phone number, and an audio timeline. Everything the
   * panel reports is unchanged.
   */
  channel?: Channel
  /** Confirmed cancellation of the scheduled call this drawer is showing. */
  onCancelCall?: () => void
  onOpenChange: (open: boolean) => void
  open: boolean
  /**
   * What is true of the clicked call rather than of the sample: its schedule,
   * and the calls on either side of it. The transcript and recording below
   * stay shared — twelve transcripts is not what this mockup is for — but
   * nothing that tells one row from another should be.
   */
  specifics?: CallSpecifics
  /** The clicked row's own identity, so every row does not open one call. */
  title?: CallIdentity
  /**
   * A queued or scheduled call has no recording, transcript, outcome or
   * collected data, so the split and the panel are not what it needs — it gets
   * the one thing that exists instead.
   */
  state?: CallState
}) {
  const call = CALL_DETAIL
  const [at, setAt] = React.useState(0)
  const content = React.useRef<HTMLDivElement>(null)

  /**
   * Dragging the handle past a half's minimum snaps that half shut rather than
   * stopping at the minimum. Reading a transcript and reading the panel are
   * different jobs, and the reader doing one of them wants the whole drawer for
   * it — a 35% strip of the other is not a compromise, it is two cramped halves.
   *
   * The collapsed half keeps its handle, so it drags back. `hidden` exists so
   * there is also a button for it: a 4px separator against the edge of the
   * sheet is a target you have to know about to find.
   */
  const transcript = React.useRef<PanelImperativeHandle>(null)
  const panel = React.useRef<PanelImperativeHandle>(null)
  const [hidden, setHidden] = React.useState<"none" | "panel" | "transcript">(
    "none",
  )

  const markers = CALL_FLAGS.map((flag) => ({
    id: flag.id,
    label: ISSUE_TYPE_LABELS[flag.issueType],
    timestampMs: flag.timestampMs,
    tone: ISSUE_TONE[flag.issueType],
  }))

  return (
    <Sheet onOpenChange={onOpenChange} open={open}>
      <SheetContent
        /* The drawer is sized to what it has to show. Six columns of width
           exist for a transcript beside a panel; a scheduled call has one card
           and would otherwise sit marooned in the middle of an empty sheet. */
        className={cn(
          "flex w-full flex-col lg:overflow-hidden",
          state === "complete" ? "sm:max-w-6xl!" : "sm:max-w-xl!",
        )}
        /**
         * Without this, touching the resize handle shuts the drawer.
         *
         * The dialog does not decide "was that click outside me?" by asking the
         * DOM. It sets a flag from its own React pointer-down handler, and
         * treats a missing flag as outside. The resize separator listens for
         * pointer-down natively and stops the event there — so React's handler
         * never runs, the flag is never set, and a press on the handle is read
         * as a press on the page behind the drawer.
         *
         * So answer the question the dialog was actually asking: if the press
         * really landed inside this panel, it was not outside. A genuine click
         * on the overlay still closes, and so do Escape and the close button.
         */
        onPointerDownOutside={(event) => {
          const target = event.detail.originalEvent.target
          if (target instanceof Node && content.current?.contains(target)) {
            event.preventDefault()
          }
        }}
        ref={content}
        /* The close button sat on top of the Call ID button in the header.
           Escape and a click on the overlay both still shut the drawer. */
        showCloseButton={false}
      >
        <SheetTitle className="sr-only">Call Details</SheetTitle>
        <SheetDescription className="sr-only">
          {call.scenario}, {call.phoneNumber}, {call.startedAt}
        </SheetDescription>

        <div className="flex min-h-0 flex-1 flex-col">
          <CallHeader
            channel={channel}
            actions={
              hidden === "none" ? null : (
                <Button
                  onClick={() => {
                    ;(hidden === "transcript"
                      ? transcript
                      : panel
                    ).current?.expand()
                  }}
                  size="sm"
                  variant="outline"
                >
                  <ShowPanelIcon />
                  {hidden === "transcript" ? "Show transcript" : "Show panel"}
                </Button>
              )
            }
            state={state}
            title={title}
          />

          {/* How much room a transcript needs against how much the panel needs
              min and max sizes are the part that is still ours: without them
              either half can be dragged away to nothing.

              The split resets each time the drawer opens. Unlike the section
              order it is a reading choice for this call, not a standing
              preference, and `defaultLayout` is only read when the group mounts
              — which the drawer does and undoes on every open. */}
          {state !== "complete" ? (
            <div className="scrollbar-hide min-h-0 flex-1 overflow-y-auto p-4">
              <PreCallPanel
                onCancel={() => onCancelCall?.()}
                specifics={specifics}
                state={state}
              />
            </div>
          ) : (
            <>
              {/* A completed call that was booked, or that booked one, says so
                  above the transcript. Buried in the panel beside insights and
                  collected data it reads as one more field; the relationship to
                  another call is the frame for everything under it. */}
              {specifics.ranFrom || specifics.booked ? (
                <div className="flex shrink-0 flex-col gap-2 px-4 pt-4">
                  {specifics.ranFrom ? (
                    <LinkedCall label="Ran from" link={specifics.ranFrom} />
                  ) : null}
                  {specifics.booked ? (
                    <LinkedCall
                      label="Callback booked"
                      link={specifics.booked}
                    />
                  ) : null}
                </div>
              ) : null}

              {specifics.schedule ? (
                <div className="shrink-0 px-4 pt-2">
                  <CompletedScheduleSummary schedule={specifics.schedule} />
                </div>
              ) : null}

              <ResizablePanelGroup
                className="min-h-0 flex-1 p-4"
                orientation="horizontal"
              >
                {/* Sizes are strings on purpose: react-resizable-panels reads a
                bare number as pixels and a string as a percentage.

                `minSize` is now the point a half gives up rather than the point
                it stops shrinking — a collapsible panel dragged under its
                minimum collapses. Neither half caps its width any more, since
                either one has to be able to reach the full drawer. */}
                <ResizablePanel
                  collapsible
                  defaultSize="62%"
                  id="transcript"
                  minSize="35%"
                  onResize={(size) => {
                    setHidden((current) =>
                      size.asPercentage === 0
                        ? "transcript"
                        : current === "transcript"
                          ? "none"
                          : current,
                    )
                  }}
                  panelRef={transcript}
                >
                  <TranscriptPanel
                    actions={<FlagDialog at={at} />}
                    at={at}
                    channel={channel}
                    flags={markers}
                    onSeek={setAt}
                  />
                </ResizablePanel>

                <ResizableHandle className="mx-4" withHandle />

                <ResizablePanel
                  collapsible
                  defaultSize="38%"
                  id="panel"
                  minSize="22%"
                  onResize={(size) => {
                    setHidden((current) =>
                      size.asPercentage === 0
                        ? "panel"
                        : current === "panel"
                          ? "none"
                          : current,
                    )
                  }}
                  panelRef={panel}
                >
                  <SectionRegister onSeek={setAt} />
                </ResizablePanel>
              </ResizablePanelGroup>
            </>
          )}
        </div>
      </SheetContent>
    </Sheet>
  )
}

const COMMENT_LIMIT = 1000

/**
 * Flagging an issue, as the app does it.
 *
 * It lives beside the player rather than in the header because a flag is
 * anchored to a millisecond in the recording, not to the call as a whole — which
 * is also why a call carries several and why this creates rather than toggles.
 */
function FlagDialog({ at }: { at: number }) {
  const [open, setOpen] = React.useState(false)
  const [issueType, setIssueType] = React.useState<IssueType | "">("")
  const [comment, setComment] = React.useState("")

  function close() {
    setOpen(false)
    setIssueType("")
    setComment("")
  }

  return (
    <Dialog
      onOpenChange={(next) => {
        if (next) setOpen(true)
        else close()
      }}
      open={open}
    >
      <DialogTrigger asChild>
        {/* Ghost, like everything else on the transport row — an outline
            button in there reads as the one thing you are meant to press. */}
        <Button size="sm" variant="ghost">
          <FlagIcon />
          Flag Issue
        </Button>
      </DialogTrigger>

      <DialogContent className="sm:max-w-md">
        <DialogHeader>
          <DialogTitle>Flag Call Issue</DialogTitle>
          <DialogDescription>
            Report an issue with this call at {formatTimeSeconds(at)}.
          </DialogDescription>
        </DialogHeader>

        <Field>
          <FieldLabel htmlFor="flag-issue-type">Issue type</FieldLabel>
          <Select
            onValueChange={(value) => {
              setIssueType(value as IssueType)
            }}
            value={issueType}
          >
            <SelectTrigger id="flag-issue-type">
              <SelectValue placeholder="Select an issue type" />
            </SelectTrigger>
            <SelectContent>
              {ISSUE_TYPE_ORDER.map((type) => (
                <SelectItem key={type} value={type}>
                  <span className="flex items-center gap-2">
                    <span
                      className={cn("size-2 rounded-4xl", ISSUE_TONE[type])}
                    />
                    {ISSUE_TYPE_LABELS[type]}
                  </span>
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
        </Field>

        <Field>
          <FieldLabel htmlFor="flag-comment">Comment</FieldLabel>
          <Textarea
            id="flag-comment"
            maxLength={COMMENT_LIMIT}
            onChange={(event) => {
              setComment(event.target.value)
            }}
            placeholder="What went wrong at this moment?"
            rows={4}
            value={comment}
          />
          <span className="text-xs text-muted-foreground tabular-nums">
            {comment.length} / {COMMENT_LIMIT}
          </span>
        </Field>

        <DialogFooter>
          <DialogClose asChild>
            <Button variant="ghost">Cancel</Button>
          </DialogClose>
          <Button disabled={!issueType} onClick={close}>
            Save
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  )
}

"use client"

import {
  AiMagicIcon,
  Alert02Icon,
  ArrowDown01Icon,
  ArrowDownLeft01Icon,
  ArrowUp01Icon,
  ArrowUpRight01Icon,
  BotIcon,
  Building02Icon,
  ArrowRight02Icon,
  Cancel01Icon,
  Comment01Icon,
  Database01Icon,
  DragDropVerticalIcon,
  Flag02Icon,
  GlobeIcon,
  Idea01Icon,
  NoteIcon,
  PlusSignCircleIcon,
  PreferenceVerticalIcon,
  Search01Icon,
  SidebarRight01Icon,
  SmileIcon,
  ListViewIcon,
  BubbleChatIcon,
  Message01Icon,
  PauseIcon as PauseSource,
  PlayCircleIcon,
  PlugSocketIcon,
  PlusSignIcon,
  UserIcon,
  Wrench01Icon,
  Calendar03Icon,
  CallOutgoing01Icon,
  CancelCircleIcon,
  Link04Icon,
  CheckListIcon,
  CheckmarkCircle02Icon,
  Clock01Icon,
  Copy01Icon,
  DashboardSpeed01Icon,
  Download01Icon,
  HeadsetIcon,
  Link02Icon,
  Loading03Icon,
  PlayIcon,
  Tick02Icon,
  VoiceIcon,
} from "@hugeicons/core-free-icons"

import { icon } from "@/components/shared/icon"

/* The drawer header. */
export const InboundIcon = icon(ArrowDownLeft01Icon, "InboundIcon")
export const OutboundIcon = icon(ArrowUpRight01Icon, "OutboundIcon")
export const CopyLinkIcon = icon(Link02Icon, "CopyLinkIcon")

/* The recording player. */
export const PlayCallIcon = icon(PlayIcon, "PlayCallIcon")
export const PauseIcon = icon(PauseSource, "PauseIcon")
export const SpeedIcon = icon(DashboardSpeed01Icon, "SpeedIcon")
export const DownloadIcon = icon(Download01Icon, "DownloadIcon")

/* Whoever is speaking, in the transcript. */
export const AgentIcon = icon(BotIcon, "AgentIcon")
export const CallerIcon = icon(UserIcon, "CallerIcon")
export const HumanAgentIcon = icon(HeadsetIcon, "HumanAgentIcon")

/* Status, outcome, and the criteria list. */
export const CompletedIcon = icon(CheckmarkCircle02Icon, "CompletedIcon")
export const FailureIcon = icon(CancelCircleIcon, "FailureIcon")
export const RunningIcon = icon(Loading03Icon, "RunningIcon")
export const NoticeIcon = icon(Alert02Icon, "NoticeIcon")
export const TimeIcon = icon(Clock01Icon, "TimeIcon")
export const ScheduledIcon = icon(Calendar03Icon, "ScheduledIcon")
export const TransferIcon = icon(CallOutgoing01Icon, "TransferIcon")
export const VoicemailIcon = icon(VoiceIcon, "VoicemailIcon")

/* Copying a data section. */
export const CopyIcon = icon(Copy01Icon, "CopyIcon")
export const CopiedIcon = icon(Tick02Icon, "CopiedIcon")

/* The revamp. */
export const SeekIcon = icon(PlayCircleIcon, "SeekIcon")
export const CorrectionIcon = icon(AiMagicIcon, "CorrectionIcon")
export const BackchannelIcon = icon(Message01Icon, "BackchannelIcon")
export const ToolIcon = icon(PlugSocketIcon, "ToolIcon")
export const InsightsIcon = icon(Idea01Icon, "InsightsIcon")
