/**
 * Addresses for the design system.
 *
 * Every topic in `DOCS_SECTIONS` is a real URL rather than a client-side tab,
 * so a page can be sent to someone. There are two shapes:
 *
 *   /design-system                       the overview — every topic listed
 *   /design-system/<section>/<page>      one topic
 *
 * A section is not one of them. It is a shelf in the rail, and clicking it
 * opens the shelf — so `/design-system/<section>` is a 404 rather than a page
 * listing what the rail is already listing one row below.
 *
 * Nested rather than flat because a bare `/design-system/data` does not say
 * whether it is the shadcn shelf or something about tables, and a link is read
 * before it is opened. The section segment answers that in the address bar.
 *
 * Derived from `DOCS_SECTIONS` rather than listed again here: the rail and the
 * routes are the same tree, and two copies of it would drift the first time a
 * topic moved between sections.
 */

import {
  DOCS_SECTIONS,
  type DocsPage,
  type DocsSection,
} from "@/lib/design-system/data"

export const DOCS_ROOT = "/design-system"

/** Topic id → the section it is filed under. */
const SECTION_OF = new Map<string, string>(
  DOCS_SECTIONS.flatMap((section) =>
    section.groups.flatMap((group) =>
      group.pages.map((page) => [page.id, section.id] as const),
    ),
  ),
)

/** Topic id → the topic, for turning a slug back into a title. */
const PAGE_OF = new Map<string, DocsPage>(
  DOCS_SECTIONS.flatMap((section) =>
    section.groups.flatMap((group) =>
      group.pages.map((page) => [page.id, page] as const),
    ),
  ),
)

const SECTION_BY_ID = new Map<string, DocsSection>(
  DOCS_SECTIONS.map((section) => [section.id, section]),
)

/** The URL for one topic. */
export function docsHref(id: string): string {
  const sectionId = SECTION_OF.get(id)

  /* A topic with no section cannot be addressed, so it falls back to the
     overview rather than minting a URL that 404s. */
  return sectionId ? `${DOCS_ROOT}/${sectionId}/${id}` : DOCS_ROOT
}

/** What a URL resolves to. `page` is null on the overview. */
export type DocsLocation = {
  section: DocsSection | null
  page: DocsPage | null
  /** What the rail marks as current: a topic id, or "" on the overview. */
  activeId: string
}

/**
 * Turn the catch-all segments into a location, or null if they name nothing.
 *
 * A null is a 404 rather than a redirect to the overview: a link that silently
 * lands somewhere else is worse than one that says it is broken, because the
 * sender never finds out they sent the wrong thing.
 */
export function resolveDocs(slug?: string[]): DocsLocation | null {
  if (!slug?.length) return { activeId: "", page: null, section: null }

  const [sectionId, pageId, ...rest] = slug
  if (rest.length) return null

  const section = SECTION_BY_ID.get(sectionId)
  if (!section) return null

  /* A section has no page of its own: the rail opens it in place. */
  if (!pageId) return null

  /* The topic has to be under this section, not merely exist: without the
     check, `/design-system/motion/colour` would render the colour page under
     a heading that says Motion. */
  if (SECTION_OF.get(pageId) !== sectionId) return null

  const page = PAGE_OF.get(pageId)
  if (!page) return null

  return { activeId: page.id, page, section }
}

/** Every address the docs answer to, for `generateStaticParams`. */
export function docsParams(): { slug: string[] | undefined }[] {
  return [
    { slug: undefined },
    ...DOCS_SECTIONS.flatMap((section) =>
      section.groups.flatMap((group) =>
        group.pages.map((page) => ({ slug: [section.id, page.id] })),
      ),
    ),
  ]
}

/**
 * The animation kernel every reel is built on.
 *
 * One rule holds the whole system together: **a reel is a pure function of one
 * integer.** Given a frame number, the composition renders exactly one picture,
 * every time, on any machine. No timers, no CSS transitions, no `animate-*`.
 *
 * That single constraint is what lets the browser preview and the MP4 render be
 * the same code. Playback is a rAF loop that advances the number; rendering is
 * a Playwright loop that sets the number and screenshots. Neither knows about
 * the other, and they cannot disagree — which is the failure mode of recording
 * a screen: the recording is a performance, and a performance is different
 * every take.
 *
 * The easings are the design system's own curves from globals.css, ported to
 * JS. They have to be values here rather than `ease-out-cubic` classes, because
 * the whole point is that nothing animates itself.
 */

/** Frames per second, everywhere. 30 is plenty for UI motion and halves the
 *  render time against 60 — there is no fast pan in a product reel. */
export const FPS = 30

/** Seconds to frames. Compositions are written in seconds and read in frames. */
export function seconds(value: number): number {
  return Math.round(value * FPS)
}

/** Frames back to a clock string, for the player's timecode. */
export function timecode(frame: number): string {
  const total = Math.max(0, Math.round(frame / FPS))
  const mins = Math.floor(total / 60)
  const secs = total % 60
  return `${mins}:${String(secs).padStart(2, "0")}`
}

/** A rectangle in some source's own pixels — a screenshot's, usually. */
export type Rect = { x: number; y: number; width: number; height: number }

export type Easing = (t: number) => number

/**
 * A cubic-bezier solver, Newton-Raphson with a fixed iteration count.
 *
 * Fixed rather than converging on a tolerance so the answer never depends on
 * how long the machine was willing to think about it — a frame rendered on a
 * busy laptop has to equal the same frame rendered on CI.
 */
function cubicBezier(x1: number, y1: number, x2: number, y2: number): Easing {
  const a = (m: number, n: number) => 1 - 3 * n + 3 * m
  const b = (m: number, n: number) => 3 * n - 6 * m
  const c = (m: number) => 3 * m

  const calc = (t: number, m: number, n: number) =>
    ((a(m, n) * t + b(m, n)) * t + c(m)) * t
  const slope = (t: number, m: number, n: number) =>
    3 * a(m, n) * t * t + 2 * b(m, n) * t + c(m)

  return (x) => {
    if (x <= 0) return 0
    if (x >= 1) return 1

    let t = x
    for (let i = 0; i < 8; i += 1) {
      const d = slope(t, x1, x2)
      if (d === 0) break
      t -= (calc(t, x1, x2) - x) / d
    }

    return calc(t, y1, y2)
  }
}

/** `--ease-out-cubic`. Anything entering or leaving. */
export const easeOutCubic = cubicBezier(0.215, 0.61, 0.355, 1)

/** `--ease-in-out-cubic`. An on-screen element resizing or moving. */
export const easeInOutCubic = cubicBezier(0.645, 0.045, 0.355, 1)

/**
 * Overshoots past the target and settles back.
 *
 * The one curve here with no counterpart in `globals.css`, and deliberately so:
 * nothing in the app overshoots, because overshoot on a real control reads as
 * a bug. On a cursor release it is the opposite — it is the only thing that
 * makes a click read as a click rather than a scale animation.
 */
export const easeOutBack: Easing = (t) =>
  1 + 2.70158 * (t - 1) ** 3 + 1.70158 * (t - 1) ** 2

/** No curve. For a camera drift that must not accelerate. */
export const linear: Easing = (t) => t

/**
 * Map a frame onto a value through a set of stops.
 *
 *     interpolate(frame, [0, 12], [0, 1])            // fade in over 12 frames
 *     interpolate(frame, [0, 12, 90, 102], [0, 1, 1, 0])  // in, hold, out
 *
 * Clamps at both ends by default, because an un-clamped value that keeps
 * growing past its last stop is never what a composition wants and is
 * invisible until the one frame where it flies off the canvas.
 */
export function interpolate(
  frame: number,
  input: readonly number[],
  output: readonly number[],
  options: { easing?: Easing; clamp?: boolean } = {},
): number {
  const { easing = easeOutCubic, clamp = true } = options

  if (input.length !== output.length || input.length < 2) {
    throw new Error("interpolate needs matching input and output stops")
  }

  if (clamp) {
    if (frame <= input[0]) return output[0]
    if (frame >= input[input.length - 1]) return output[output.length - 1]
  }

  let i = 0
  while (i < input.length - 2 && frame >= input[i + 1]) i += 1

  const span = input[i + 1] - input[i]
  const progress = span === 0 ? 0 : (frame - input[i]) / span

  return output[i] + easing(progress) * (output[i + 1] - output[i])
}

/**
 * The entrance every element shares: rise a little, fade in.
 *
 * Returns a style object rather than classes because the value changes every
 * frame — this is exactly the "dynamic geometry" the style prop is for.
 *
 * `distance` is in canvas pixels. Keep it small: 16–32px reads as arrival,
 * 80px reads as a slide transition and pulls the eye off the words.
 */
export function enter(
  frame: number,
  options: { delay?: number; duration?: number; distance?: number } = {},
): { opacity: number; transform: string } {
  const { delay = 0, duration = 14, distance = 20 } = options
  const at = [delay, delay + duration]

  return {
    opacity: interpolate(frame, at, [0, 1]),
    transform: `translateY(${interpolate(frame, at, [distance, 0]).toFixed(3)}px)`,
  }
}

/**
 * The matching exit, measured from the end of a scene.
 *
 * A scene that only enters leaves a hard cut on its last frame. That reads as a
 * dropped frame rather than an edit, so every scene should either exit or be
 * covered by the next one arriving.
 */
export function exit(
  frame: number,
  sceneDuration: number,
  options: { duration?: number; distance?: number } = {},
): { opacity: number; transform: string } {
  const { duration = 12, distance = 16 } = options
  const start = sceneDuration - duration
  const at = [start, sceneDuration]

  return {
    opacity: interpolate(frame, at, [1, 0], { easing: easeInOutCubic }),
    transform: `translateY(${interpolate(frame, at, [0, -distance], {
      easing: easeInOutCubic,
    }).toFixed(3)}px)`,
  }
}

/** Enter and exit in one call — what most elements actually want. */
export function through(
  frame: number,
  sceneDuration: number,
  options: { delay?: number; distance?: number } = {},
): { opacity: number; transform: string } {
  const { delay = 0, distance = 20 } = options
  const a = enter(frame, { delay, distance })
  const b = exit(frame, sceneDuration)

  return {
    opacity: Math.min(a.opacity, b.opacity),
    transform: `translateY(${(
      interpolate(frame, [delay, delay + 14], [distance, 0]) +
      interpolate(frame, [sceneDuration - 12, sceneDuration], [0, -16], {
        easing: easeInOutCubic,
      })
    ).toFixed(3)}px)`,
  }
}

/** Nth item's delay in a staggered group. Keep `step` at 3–5 frames. */
export function stagger(index: number, step = 4, base = 0): number {
  return base + index * step
}

/**
 * Text matching for the index search.
 *
 * The index is a short list of long strings — a title, a ticket ID, a surface,
 * a paragraph of description — and people type into it the way they talk about
 * the work: a couple of words in any order ("drawer settings"), half a ticket
 * ID ("des149"), an abbreviation ("kb"), a word with a letter missing
 * ("trasfer"). So a term is tried against a field several ways, strongest
 * first, and the tier it lands on *is* its score.
 *
 * Everything here is one term against one field. Which fields exist, what each
 * one is worth, and how the terms combine live in `mockups-data.ts`.
 */

/**
 * How much each way of matching is worth. The gaps are wide enough that a
 * weaker match in an important field can still outrank a stronger match in an
 * unimportant one — that is the point of scoring rather than filtering — but
 * not so wide that a description hit buries a title hit.
 */
const TIER = {
  /** The field is the term. */
  field: 100,
  /** A whole word in the field is the term. */
  word: 92,
  /** The field starts with the term — a partly typed title. */
  fieldPrefix: 84,
  /** A word starts with the term, which is most of what typing looks like. */
  wordPrefix: 76,
  /** The term appears mid-word. */
  substring: 60,
  /** It appears once punctuation is dropped: "des149" in "DES-149". */
  condensed: 52,
  /** A word is the term with a typo, minus `TYPO_PENALTY` per extra edit. */
  typo: 44,
  /** A word contains the term's letters in order: "trnsfr" in "transfer". */
  wordFuzzy: 20,
  /** The term reads as an initialism of the field: "kb". */
  initialism: 22,
} as const

const TYPO_PENALTY = 10

/**
 * Below this, a term is only allowed to match at the start of a word.
 *
 * Two letters land inside a long word by accident constantly — "kb" is in
 * "checkbox" — and a coincidence that beats the card the reader meant is
 * exactly the failure this search is fixing.
 */
const MIN_LOOSE_LENGTH = 3

/** How much of a word the term has to cover to earn the `wordFuzzy` tier. */
const FUZZY_COVERAGE = 14

/**
 * Lowercase and unaccented. Every comparison runs on this, never on the raw
 * text, so case and accents can never be the reason something fails to match.
 */
function normalize(text: string): string {
  return text
    .normalize("NFD")
    .replace(/\p{Diacritic}/gu, "")
    .toLowerCase()
}

/** Letters and digits only — what makes "des149" find "DES-149". */
function condense(text: string): string {
  return text.replace(/[^\p{L}\p{N}]+/gu, "")
}

const WORDS = /[\p{L}\p{N}]+/gu

/** A field, split every way a term is going to be tried against it. */
export type Field = {
  normalized: string
  condensed: string
  words: string[]
}

/* The mockup list is a fixed set of strings and this runs on every keystroke,
   so each field is split once and kept. */
const fields = new Map<string, Field>()

export function prepareField(text: string): Field {
  const cached = fields.get(text)
  if (cached) return cached

  const normalized = normalize(text)

  const field: Field = {
    normalized,
    condensed: condense(normalized),
    words: normalized.match(WORDS) ?? [],
  }
  fields.set(text, field)
  return field
}

/** One word of a query, prepared the same way the fields are. */
export type Term = {
  normalized: string
  condensed: string
}

/**
 * The query split into terms. Every term has to land somewhere to match, so
 * a term made only of punctuation is dropped rather than kept and failed —
 * one stray dash should not empty the page.
 */
export function prepareQuery(query: string): Term[] {
  return normalize(query)
    .split(/\s+/)
    .map((word) => ({ normalized: word, condensed: condense(word) }))
    .filter((term) => term.condensed)
}

/**
 * How well one term matches one field, or `null` when it does not at all.
 *
 * The tiers are tried strongest first and the first hit wins, so the score
 * says *how* it matched — which is what makes the ranking legible: an exact
 * ticket ID cannot be outranked by a stray letter in a paragraph.
 */
export function scoreTerm(term: Term, field: Field): number | null {
  const query = term.normalized
  if (!query) return null

  if (field.normalized === query) return TIER.field
  if (field.words.includes(query)) return TIER.word
  if (field.normalized.startsWith(query)) return TIER.fieldPrefix
  if (field.words.some((word) => word.startsWith(query))) return TIER.wordPrefix
  if (query.length >= MIN_LOOSE_LENGTH) {
    if (field.normalized.includes(query)) return TIER.substring
    if (term.condensed && field.condensed.includes(term.condensed)) {
      return TIER.condensed
    }
  }

  const typo = typoScore(query, field.words)
  if (typo !== null) return typo

  const fuzzy = wordFuzzyScore(query, field.words)
  if (fuzzy !== null) return fuzzy

  return initialismScore(query, field)
}

/**
 * A misspelling, scored by how far off it is.
 *
 * The edit budget scales with the term because one wrong letter in three is a
 * different word ("card" is not "call"), while one wrong letter in nine is a
 * slip. Distance is measured against every prefix of the word too, so a term
 * still being typed — "trasfer" for "transfer" — is a typo rather than a miss.
 */
function typoScore(query: string, words: string[]): number | null {
  const budget = query.length >= 7 ? 2 : query.length >= 4 ? 1 : 0
  if (budget === 0) return null

  let best: number | null = null

  for (const word of words) {
    // Nothing within budget can be this far off in length.
    if (word.length + budget < query.length) continue

    const distance = prefixEditDistance(query, word, budget)
    if (distance === null) continue
    if (best === null || distance < best) best = distance
    if (best === 1) break
  }

  return best === null ? null : TIER.typo - (best - 1) * TYPO_PENALTY
}

/**
 * The smallest edit distance between `query` and any prefix of `word`,
 * counting a swapped pair of adjacent letters as one edit, or `null` once
 * every possibility exceeds `budget`.
 *
 * Prefixes rather than the whole word because the reader is typing: "knowlege"
 * should reach "knowledge base", and it only does if the trailing " base" is
 * free rather than five more edits.
 */
function prefixEditDistance(
  query: string,
  word: string,
  budget: number,
): number | null {
  let older: number[] = []
  let previous = Array.from({ length: query.length + 1 }, (_, i) => i)
  let best: number | null =
    previous[query.length] <= budget ? previous[query.length] : null

  for (let row = 1; row <= word.length; row++) {
    const current = [row]
    let rowBest = row

    for (let column = 1; column <= query.length; column++) {
      const substitution =
        previous[column - 1] + (word[row - 1] === query[column - 1] ? 0 : 1)
      let best = Math.min(
        substitution,
        previous[column] + 1,
        current[column - 1] + 1,
      )

      /* Two letters typed in the wrong order is one slip, not two: without
         this, "vioce" is as far from "voice" as a word that shares three
         letters with it. */
      if (
        row > 1 &&
        column > 1 &&
        word[row - 1] === query[column - 2] &&
        word[row - 2] === query[column - 1]
      ) {
        best = Math.min(best, older[column - 2] + 1)
      }

      current[column] = best
      rowBest = Math.min(rowBest, best)
    }

    /* Every prefix is a candidate and a longer one can score better than a
       shorter one — "conversatoins" is two edits from "conversation" but one
       from "conversations" — so the whole word is walked for the best of
       them rather than stopping at the first that fits. */
    const distance = current[query.length]
    if (distance <= budget && (best === null || distance < best))
      best = distance
    if (best === 0) return 0

    // Distance only grows from here, so once the whole row is over budget no
    // longer prefix can come back under it.
    if (rowBest > budget) return best

    older = previous
    previous = current
  }

  return best
}

/**
 * The term's letters in order inside one word — "trnsfr" in "transfer".
 *
 * Kept to a single word on purpose. Scattering the same letters across a whole
 * description is how a subsequence match turns a paragraph into a hit for
 * almost anything, which is exactly the noise this search is fixing.
 */
function wordFuzzyScore(query: string, words: string[]): number | null {
  if (query.length < 3) return null

  let best: number | null = null

  for (const word of words) {
    // A short term inside a long word is a coincidence, not an abbreviation.
    if (word.length > query.length * 2) continue
    if (word[0] !== query[0]) continue
    if (!isSubsequence(query, word)) continue

    const coverage = query.length / word.length
    const score = TIER.wordFuzzy + coverage * FUZZY_COVERAGE
    if (best === null || score > best) best = score
  }

  return best
}

function isSubsequence(query: string, word: string): boolean {
  let cursor = 0
  for (const char of word) {
    if (char === query[cursor]) cursor++
    if (cursor === query.length) return true
  }
  return false
}

/**
 * The term read as an initialism: "kb" for "Knowledge base", "confrep" for
 * "Configure Report".
 *
 * The words have to be *next to each other* and each run has to start one.
 * An initialism assembled from words scattered through a paragraph is not an
 * initialism — it is a coincidence, and in a field this long there is one for
 * almost any three letters.
 */
const INITIALISM_MAX_LENGTH = 10
const INITIALISM_MAX_CHUNKS = 3

function initialismScore(query: string, field: Field): number | null {
  if (query.length < 2 || query.length > INITIALISM_MAX_LENGTH) return null
  if (!field.words.length) return null

  const chunks = matchChunks(query, 0, field, 0, 0)
  if (chunks === null) return null

  return TIER.initialism - (chunks - 1) * 2
}

/**
 * Walks the term from `cursor`, taking as much as possible from each word it
 * starts at, and backtracking to a shorter run when the rest cannot be placed.
 * Returns how many runs it took, or `null` if it does not fit in the cap.
 *
 * `wordFrom` is where the next run may start: anywhere for the first one,
 * and the very next word for every one after it.
 */
function matchChunks(
  query: string,
  cursor: number,
  field: Field,
  wordFrom: number,
  used: number,
): number | null {
  if (cursor === query.length) return used
  if (used === INITIALISM_MAX_CHUNKS) return null

  // The first run may start at any word; every run after it continues from
  // the word immediately following the one before.
  const last = Math.min(
    used === 0 ? field.words.length - 1 : wordFrom,
    field.words.length - 1,
  )

  for (let index = wordFrom; index <= last; index++) {
    const word = field.words[index]
    if (word[0] !== query[cursor]) continue

    // How much of the rest of the term this word can absorb.
    let run = 1
    while (
      run < word.length &&
      cursor + run < query.length &&
      word[run] === query[cursor + run]
    ) {
      run++
    }

    // Longest run first: it is both the likelier reading and the one that
    // leaves the fewest runs to place.
    for (let length = run; length >= 1; length--) {
      const rest = matchChunks(
        query,
        cursor + length,
        field,
        index + 1,
        used + 1,
      )
      if (rest !== null) return rest
    }
  }

  return null
}

import { CallOutgoing01Icon } from "@hugeicons/core-free-icons"
import type { IconSvgElement } from "@hugeicons/react"

import { FPS } from "@/lib/reels/anim"

/**
 * The reel index. One video, one route, one card — the same contract the
 * mockup index runs on, for the same reason: a reel nobody can find is a reel
 * that gets rebuilt from scratch next release.
 *
 * A reel is **not** a filled-in template. Each one is its own React
 * composition under `src/components/reels/<slug>/`, written for what that
 * release actually shipped. The shared pieces — the canvas, the camera, the
 * type — are in `src/components/reels/`, and they are what keep every reel on
 * brand without making every reel look the same.
 */
export type Reel = {
  /** Route, and the reel's identity in this list. */
  href: string
  title: string
  /** Shape and length, e.g. "Release reel · 38s". */
  meta: string
  description: string
  icon: IconSvgElement
  /** Total frames. Must match the composition's own `DURATION`. */
  duration: number
}

export const REELS: Reel[] = [
  {
    href: "/reels/callback-tool",
    title: "Callback tool",
    meta: "Release reel · 38s",
    description:
      "The scheduling tool a scenario can hand a caller, shown in the scenario editor and on a live call.",
    icon: CallOutgoing01Icon,
    duration: 38 * FPS,
  },
  // `npm run new:reel` appends new reels above this line.
]

/** Seconds, for a card that wants to print a length. */
export function reelLength(reel: Reel): string {
  return `${Math.round(reel.duration / FPS)}s`
}

import { clsx, type ClassValue } from "clsx"
import { twMerge } from "tailwind-merge"

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs))
}
